package li.cil.oc.plusplus;
import org.junit.Test;
import static org.junit.Assert.*;
import static li.cil.oc.plusplus.BiosBootState.*;

public class BiosBootStateTest {
 @Test public void menuHitWhitelistAndUnloadCannotBecomeGuestCommands(){assertEquals(10,BiosBootState.actionAt(0,.5,.3));assertEquals(12,BiosBootState.actionAt(0,.5,.6));assertEquals(0,BiosBootState.actionAt(3,.5,.55));assertEquals(4,BiosBootState.actionAt(2,.5,.9));assertEquals(-1,BiosBootState.actionAt(1,.5,.55));assertEquals(-1,BiosBootState.actionAt(0,Double.NaN,.3));assertEquals(-1,BiosBootState.actionAt(9,.5,.3));BiosBootState b=new BiosBootState();b.power(Dependency.OFFLINE_BIOS,true,0);long e=b.epoch();b.shutdown();assertFalse(b.mayProject());assertTrue(b.epoch()>e);assertFalse(b.key(Key.ENTER,e,true));}
 @Test public void offAndMissingNeverProjectSuccessfulBios(){BiosBootState b=new BiosBootState();assertFalse(b.mayProject());Transition t=b.power(Dependency.MISSING,true,0);assertTrue(t.accepted&&t.beep);assertEquals(State.ERROR,b.state());assertEquals(BiosBootState.Error.MISSING_DEPENDENCY,b.error());assertFalse(b.mayProject());assertFalse(b.engineReady());}
 @Test public void incompatibleDependencyErrorsAndOnlyExplicitRequestBeeps(){BiosBootState b=new BiosBootState();assertTrue(b.power(Dependency.INCOMPATIBLE,true,0).beep);assertEquals(BiosBootState.Error.INCOMPATIBLE_DEPENDENCY,b.error());long epoch=b.epoch();b.dependencyChanged(Dependency.OFFLINE_BIOS);assertEquals(State.ERROR,b.state());assertTrue(b.epoch()>epoch);assertFalse(b.mayProject());}
 @Test public void compatibleOfflineCompanionBootsInteractiveBiosWithoutEngine(){BiosBootState b=new BiosBootState();Transition t=b.power(Dependency.OFFLINE_BIOS,true,0);assertTrue(t.accepted&&!t.beep);assertTrue(b.mayProject());assertFalse(b.engineReady());assertFalse(b.mayExecuteGuest());long e=b.epoch();assertTrue(b.key(Key.DOWN,e,true));assertEquals(1,b.selection());assertTrue(b.key(Key.ENTER,e,true));assertEquals(Page.SYSTEM,b.page());assertTrue(b.key(Key.BACK,e,true));assertEquals(Page.MAIN,b.page());}
 @Test public void missingToValidRequiresNewPowerRequest(){BiosBootState b=new BiosBootState();b.power(Dependency.MISSING,true,0);b.dependencyChanged(Dependency.OFFLINE_BIOS);assertFalse(b.mayProject());assertFalse(b.power(Dependency.OFFLINE_BIOS,true,39).accepted);assertTrue(b.power(Dependency.OFFLINE_BIOS,true,40).accepted);assertTrue(b.mayProject());}
 @Test public void powerOffAndDependencyLossRevokeOldInput(){BiosBootState b=new BiosBootState();b.power(Dependency.OFFLINE_BIOS,true,0);long e=b.epoch();assertTrue(b.power(Dependency.OFFLINE_BIOS,true,40).accepted);assertEquals(State.OFF,b.state());assertFalse(b.key(Key.ENTER,e,true));b.power(Dependency.OFFLINE_BIOS,true,80);e=b.epoch();b.dependencyChanged(Dependency.MISSING);assertFalse(b.mayProject());assertFalse(b.click(.5,.3,e,true));}
 @Test public void unauthorizedInputAndRateLimitDoNotChangeState(){BiosBootState b=new BiosBootState();assertFalse(b.power(Dependency.ENGINE_READY,false,0).accepted);assertEquals(State.OFF,b.state());assertEquals(0,b.epoch());b.power(Dependency.OFFLINE_BIOS,true,0);long e=b.epoch();assertFalse(b.key(Key.DOWN,e,false));assertFalse(b.key(Key.DOWN,e-1,true));assertFalse(b.power(Dependency.MISSING,true,1).accepted);assertEquals(State.BIOS,b.state());assertFalse(b.power(Dependency.MISSING,true,-1).accepted);}
 @Test public void normalizedMenuClicksNavigateTheSharedPage(){BiosBootState b=new BiosBootState();b.power(Dependency.OFFLINE_BIOS,true,0);long e=b.epoch();assertTrue(b.click(.5,.6,e,true));assertEquals(Page.DIAGNOSTICS,b.page());assertTrue(b.click(.5,.9,e,true));assertEquals(Page.MAIN,b.page());assertFalse(b.click(.5,.39,e,true));assertFalse(b.click(Double.NaN,.3,e,true));assertFalse(b.click(.5,Double.POSITIVE_INFINITY,e,true));assertFalse(b.click(1.1,.3,e,true));}
 @Test public void engineReadinessNeverGrantsGuestExecutionAndCounterCannotWrap(){BiosBootState b=new BiosBootState();b.power(Dependency.ENGINE_READY,true,Long.MAX_VALUE);assertTrue(b.engineReady()&&b.mayProject());assertFalse(b.mayExecuteGuest());assertFalse(b.power(Dependency.ENGINE_READY,true,Long.MAX_VALUE).accepted);assertFalse(b.power(Dependency.ENGINE_READY,true,0).accepted);}
 @Test public void layoutChangeRevokesStaleCoordinatesWithoutRestartingBios(){BiosBootState b=new BiosBootState();b.power(Dependency.OFFLINE_BIOS,true,0);long e=b.epoch();b.key(Key.ENTER,e,true);b.layoutChanged();assertEquals(Page.LIBRARY,b.page());assertTrue(b.mayProject());assertFalse(b.click(.5,.9,e,true));assertTrue(b.click(.5,.9,b.epoch(),true));}
}
